-- ShipBits Distribution Seed 004 — PostYourStartup + user-supplied directories
-- Generated from the exact aggregator data supplied by the user on 2026-08-31.
--
-- IMPORTANT:
-- The user explicitly requested that DR / traffic / pricing / link-type claims from
-- the aggregator be copied without independent verification.
--
-- Mapping used:
--   PostYourStartup DR       -> authority_score
--   PostYourStartup Traffic  -> submission_requirements.aggregator_claims.traffic
--                               (raw string preserved; traffic_tier stays NULL)
--   Price Free               -> pricing_type='free'
--   Price Paid               -> pricing_type='paid'
--   Price ?                  -> pricing_type='unknown'
--   Links Do                 -> backlink_possible=true,  dofollow_possible=true
--   Links No                 -> backlink_possible=true,  dofollow_possible=false
--   Links ?                  -> both NULL
--
-- p_force is FALSE for every RPC call.
-- Existing administrator overrides therefore remain protected.
--
-- WARNING:
-- For canonical URLs that already exist from earlier researched batches, this seed
-- can update non-admin-overridden fields with the aggregator claims (for example
-- pricing/authority data), because that is the requested behavior.

BEGIN;

