-- Summary
SELECT
  count(*) AS supplied_batch_004_rows,
  count(*) FILTER (WHERE status = 'active') AS active,
  count(*) FILTER (WHERE status = 'inactive') AS inactive,
  count(*) FILTER (WHERE status = 'rejected') AS rejected,
  count(*) FILTER (WHERE authority_score IS NOT NULL) AS rows_with_copied_dr,
  count(*) FILTER (WHERE pricing_type = 'free') AS free,
  count(*) FILTER (WHERE pricing_type = 'paid') AS paid,
  count(*) FILTER (WHERE pricing_type = 'unknown') AS pricing_unknown,
  count(*) FILTER (WHERE dofollow_possible IS TRUE) AS dofollow_claimed,
  count(*) FILTER (WHERE dofollow_possible IS FALSE) AS nofollow_claimed
FROM public.distribution_channels
WHERE canonical_url IN (
  SELECT x->>'canonical_url'
  FROM jsonb_array_elements($shipbits$
