SELECT
  name,
  channel_type,
  authority_score AS copied_dr,
  submission_requirements #>> '{aggregator_claims,traffic}' AS copied_traffic,
  pricing_type,
  price_amount,
  price_currency,
  backlink_possible,
  dofollow_possible,
  status,
  canonical_url
FROM public.distribution_channels
WHERE canonical_url IN (
  SELECT x->>'canonical_url'
  FROM jsonb_array_elements($shipbits$
[
  {
    "name": "SourceForge",
    "slug": "sourceforge",
    "description": "SourceForge is a startup, software, or technology discovery directory.",
    "website_url": "https://sourceforge.net",
    "canonical_url": "https://sourceforge.net",
    "submission_url": null,
    "channel_type": "directory",
    "pricing_type": "free",
    "price_amount": null,
